import scrapy

class QuotesSpider(scrapy.Spider):
    name = "quotes"
    start_urls = ["https://quotes.toscrape.com/"]
    custom_settings = {
        "FEEDS": {
            "out/%(name)s.jsonl": {"format": "jsonlines", "overwrite": True},
            "out/%(name)s.csv": {"format": "csv", "fields": ["author", "text"]},
        },
        "FEED_EXPORT_ENCODING": "utf-8",
    }

    def parse(self, response):
        for q in response.css("div.quote"):
            yield {
                "text": q.css("span.text::text").get(),
                "author": q.css("small.author::text").get(),
                "tags": q.css("a.tag::text").getall(),
            }

# $ scrapy runspider quotes.py            -> out/quotes.jsonl and out/quotes.csv
# $ scrapy runspider quotes.py -O q.json  -> also a JSON array

import scrapy

class AuthorsSpider(scrapy.Spider):
    name = "authors"
    allowed_domains = ["quotes.toscrape.com"]
    start_urls = ["https://quotes.toscrape.com/"]

    def parse(self, response):
        for q in response.css("div.quote"):
            about = q.css("span a")      # the (about) link
            yield response.follow(about[0], callback=self.parse_author,
                                  cb_kwargs={"first_quote": q.css("span.text::text").get()})
        yield from response.follow_all(css="li.next a", callback=self.parse)

    def parse_author(self, response, first_quote):
        yield {
            "name": response.css("h3.author-title::text").get().strip(),
            "born": response.css("span.author-born-date::text").get(),
            "first_quote_seen": first_quote[:30],
        }
# Each author page is fetched once, even if linked from many quotes.

