from itemadapter import ItemAdapter
from scrapy.exceptions import DropItem

class ValidatePipeline:
    def process_item(self, item):
        a = ItemAdapter(item)
        if not a.get("title") or a.get("price") is None:
            raise DropItem(f"missing fields: {a.asdict()}")
        a["price"] = round(float(a["price"]), 2)
        return item

class DedupePipeline:
    def open_spider(self):
        self.seen = set()
    def process_item(self, item):
        key = ItemAdapter(item)["title"].lower()
        if key in self.seen:
            raise DropItem(f"duplicate: {key}")
        self.seen.add(key)
        return item

