import scrapy
from form2request import form2request

class AccountSpider(scrapy.Spider):
    name = "account"
    start_urls = ["https://quotes.toscrape.com/login"]

    def parse(self, response):
        # keeps hidden fields like csrf_token, fills in ours
        req = form2request(response.css("form"), {"username": "demo", "password": "demo"})
        yield req.to_scrapy(callback=self.after_login)

    def after_login(self, response):
        if "Logout" not in response.text:
            self.logger.error("login failed"); return
        yield response.follow("/api/quotes?page=1", callback=self.parse_api)

    def parse_api(self, response):
        data = response.json()
        for q in data["quotes"]:
            yield {"author": q["author"]["name"], "text": q["text"]}
        if data["has_next"]:
            yield response.follow(f"/api/quotes?page={data['page'] + 1}",
                                  callback=self.parse_api)

