import random
from scrapy.exceptions import IgnoreRequest

class ProxyAndBanMiddleware:
    def __init__(self, proxies):
        self.proxies = proxies
    @classmethod
    def from_crawler(cls, crawler):
        return cls(crawler.settings.getlist("PROXY_LIST"))
    def process_request(self, request, spider):
        if self.proxies and "proxy" not in request.meta:
            request.meta["proxy"] = random.choice(self.proxies)
        return None                                  # continue downloading
    def process_response(self, request, response, spider):
        if response.status == 403 or b"captcha" in response.body.lower():
            if request.meta.get("ban_retries", 0) >= 3:
                raise IgnoreRequest(f"banned: {request.url}")
            retry = request.replace(dont_filter=True)
            retry.meta["ban_retries"] = request.meta.get("ban_retries", 0) + 1
            retry.meta.pop("proxy", None)            # pick another proxy
            return retry
        return response

