import scrapy
from scrapy.downloadermiddlewares.retry import get_retry_request
from scrapy.spidermiddlewares.httperror import HttpError
from twisted.internet.error import DNSLookupError, TimeoutError

class RobustSpider(scrapy.Spider):
    name = "robust"
    handle_httpstatus_list = [404]
    custom_settings = {"RETRY_TIMES": 3}
    async def start(self):
        for url in ["https://quotes.toscrape.com/", "https://quotes.toscrape.com/nope"]:
            yield scrapy.Request(url, callback=self.parse, errback=self.on_error)
    def parse(self, response):
        if response.status == 404:
            yield {"url": response.url, "status": "missing"}; return
        if not response.css("div.quote"):
            retry = get_retry_request(response.request, spider=self, reason="empty")
            if retry: yield retry
            return
        yield {"url": response.url, "quotes": len(response.css("div.quote"))}
    def on_error(self, failure):
        if failure.check(HttpError):
            self.logger.error("HTTP %s on %s", failure.value.response.status, failure.request.url)
        elif failure.check(DNSLookupError, TimeoutError):
            self.logger.error("Network error on %s", failure.request.url)

import json
import scrapy

class ListingsSpider(scrapy.Spider):
    name = "listings"
    start_urls = ["https://example.com/listings"]

    def parse(self, response):
        # Option 1: data embedded by a Next.js app
        raw = response.css("script#__NEXT_DATA__::text").get()
        if raw:
            for item in json.loads(raw)["props"]["pageProps"]["listings"]:
                yield {"id": item["id"], "title": item["title"]}
            return
        # Option 2: render with a browser (scrapy-playwright)
        yield scrapy.Request(response.url, callback=self.parse_rendered,
                             meta={"playwright": True}, dont_filter=True)

    def parse_rendered(self, response):
        for card in response.css("div.listing"):
            yield {"title": card.css("h2::text").get()}

