import scrapy
from scrapy.crawler import AsyncCrawlerProcess

class TitleSpider(scrapy.Spider):
    name = "titles"

    def __init__(self, start="https://quotes.toscrape.com/", **kw):
        super().__init__(**kw)
        self.start_urls = [start]

    def parse(self, response):
        yield {"url": response.url, "title": response.css("title::text").get()}

process = AsyncCrawlerProcess(settings={
    "FEEDS": {"titles.jsonl": {"format": "jsonlines", "overwrite": True}},
    "LOG_LEVEL": "INFO",
    # "JOBDIR": "crawls/titles-1",    # enable pause/resume
})
crawler = process.create_crawler(TitleSpider)
process.crawl(crawler, start="https://quotes.toscrape.com/")
process.start()                        # blocks until the crawl finishes
print(crawler.stats.get_value("item_scraped_count"))   # 1
print(crawler.stats.get_value("finish_reason"))        # finished

import scrapy
from scrapy import signals

class FlowSpider(scrapy.Spider):
    name = "flow"
    start_urls = ["https://quotes.toscrape.com/"]

    @classmethod
    def from_crawler(cls, crawler, *args, **kwargs):
        spider = super().from_crawler(crawler, *args, **kwargs)
        crawler.signals.connect(spider.on_drop, signal=signals.request_dropped)
        crawler.signals.connect(spider.on_closed, signal=signals.spider_closed)
        return spider

    def parse(self, response):
        yield response.follow("/page/2/", priority=10)    # jumps the queue
        yield response.follow("/page/2/")                  # duplicate: dropped
        yield response.follow("/", dont_filter=True, callback=self.parse_home)
    def parse_home(self, response):
        yield {"home_again": response.url}
    def on_drop(self, request, spider):
        self.logger.info("dropped %s", request.url)
    def on_closed(self, spider, reason):
        stats = self.crawler.stats.get_stats()
        self.logger.info("filtered dupes: %s", stats.get("dupefilter/filtered"))
